    def disconnect(self, other: Cell) -> None:
        """Disconnects this cell from another cell.

        Removes all connections between self and other, regardless of keys used.

        Args:
            other (Cell): other cell to disconnect from

        """
        found = False
        new_connections = {}
        for k, v in self._connections.items():
            if v is other:
                found = True
            else:
                new_connections[k] = v
        self._connections = new_connections
        if not found:
            raise ValueError("Cannot disconnect from a cell that is not connected")
